// Brand logo (Lagos Life Forbes) -- base64-embedded directly in the
// Worker bundle rather than uploaded to R2, since this is a fixed,
// rarely-changing brand asset, not user-uploaded content; served via
// GET /og-image.jpg (see src/index.js) and referenced from every public
// page's <head> as both the favicon and the OG/Twitter social-preview
// image. Dimensions are the source file's real pixel size, needed for
// the og:image:width/height meta tags.
export const OG_IMAGE_CONTENT_TYPE = 'image/jpeg';
export const OG_IMAGE_WIDTH = 1264;
export const OG_IMAGE_HEIGHT = 843;
export const OG_IMAGE_BASE64 = '';
